bounded_host_request.command:
set -eu
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo BOT_NOT_RUNNING; exit 81; }
test "$(docker ps --format '{{.Names}}' | grep -Ec 'createvdobot|create-videobot|videobot-poll' || true)" -eq 1 || { echo BOT_MULTIPLE_CONSUMERS; exit 82; }
docker exec -i "$name" node --input-type=module - <<'NODE'
import {readFileSync} from 'node:fs';
import pg from 'pg';
const env=process.env;
const fail=(code,message)=>{console.log(message);process.exitCode=code;};
try{
 const token=readFileSync(env.VIDEOBOT_TELEGRAM_TOKEN_FILE,'utf8').trim();
 if(!token)throw Error('TOKEN_MISSING');
 const call=async(method)=>{
  const result=await fetch('https://api.telegram.org/bot'+token+'/'+method,{signal:AbortSignal.timeout(9000)});
  const body=await result.json();
  if(!result.ok||body.ok!==true)throw Error('API_FAILED');
  return body.result;
 };
 const me=await call('getMe');
 if(me.is_bot!==true||String(me.username).toLowerCase()!=='createvdobot')throw Error('BOT_IDENTITY_MISMATCH');
 console.log('LIVE_CREATEVDOBOT_IDENTITY=PASS');
 const hook=await call('getWebhookInfo');
 if(hook.url!=='')throw Error('WEBHOOK_COMPETING_WITH_POLL');
 console.log('LIVE_CREATOR_POLL_INGRESS=PASS');
 const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,database:env.VIDEOBOT_DB_NAME,user:env.VIDEOBOT_DB_USER,password:readFileSync(env.VIDEOBOT_DB_PASSWORD_FILE,'utf8').trim(),max:1});
 try {
  const r=await pool.query("SELECT status,price_stars,jsonb_array_length(items) AS items FROM videobot_sticker_products WHERE product_id=$1",['sp_76f23430d1c29ca355960a95']);
  if(r.rowCount!==1||r.rows[0].status!=='published'||Number(r.rows[0].price_stars)!==50||Number(r.rows[0].items)<1)throw Error('STICKER_PRODUCT_MISMATCH');
  console.log('EXISTING_STICKER_PRODUCT_50_STARS=PASS');
 } finally {await pool.end();}
}catch(e){
 const allowed=['TOKEN_MISSING','API_FAILED','BOT_IDENTITY_MISMATCH','WEBHOOK_COMPETING_WITH_POLL','STICKER_PRODUCT_MISMATCH'];
 const msg=allowed.includes(e.message)?e.message:'BOT_LIVE_HEALTH_CHECK_FAILED';
 fail(91,msg);
}
NODE
